using System;using System.Data;using System.IO;using System.Web;using System.Web.UI.WebControls;
namespace AQOONHUB_SMS.Modules.Communication{public partial class Announcements:CommunicationPageBase{int CurrentPage{get{return (int?)(ViewState["P"])??1;}set{ViewState["P"]=Math.Max(1,value);}}int Pages{get{return (int?)(ViewState["Pages"])??1;}set{ViewState["Pages"]=Math.Max(1,value);}}public bool CanManage{get{return CommunicationAuthorization.CanManageAnnouncements(Role);}}protected void Page_Load(object s,EventArgs e){if(!CanManage)btnNew.Visible=false;if(!IsPostBack){LoadLookups();Bind();if(Request.QueryString["new"]=="1"&&CanManage)Open(null);}}void LoadLookups(){formRole.Items.Clear();foreach(string x in new[]{"Admin","Academic","Registrar","Accountant","Teacher","Parent","Security"})formRole.Items.Add(x);formClass.DataSource=Repo.Q("SELECT ClassID,ClassName FROM dbo.Classes WHERE Status='Active' ORDER BY ClassName");formClass.DataTextField="ClassName";formClass.DataValueField="ClassID";formClass.DataBind();LoadSections();formUser.DataSource=Repo.RecipientUsers(Role,UserId);formUser.DataTextField="FullName";formUser.DataValueField="UserID";formUser.DataBind();AudiencePanels();}void LoadSections(){formSection.DataSource=Repo.Q("SELECT SectionID,SectionName FROM dbo.Sections WHERE (@c=0 OR ClassID=@c) ORDER BY SectionName",new System.Data.SqlClient.SqlParameter("@c",V(formClass.SelectedValue)));formSection.DataTextField="SectionName";formSection.DataValueField="SectionID";formSection.DataBind();}int V(string x){int n;return int.TryParse(x,out n)?n:0;}void Bind(){try{int size=PageSize(ddlPageSize.SelectedValue);CommPage p=Repo.Announcements(txtSearch.Text.Trim(),ddlAudience.SelectedValue,ddlPriority.SelectedValue,ddlStatus.SelectedValue,DateValue(txtFrom.Text),DateValue(txtTo.Text),CurrentPage,size);Pages=Math.Max(1,(int)Math.Ceiling(p.Total/(double)size));if(CurrentPage>Pages){CurrentPage=Pages;Bind();return;}gv.DataSource=p.Rows;gv.DataBind();litPage.Text="Page "+CurrentPage+" of "+Pages+" · "+p.Total+" records";btnPrev.Enabled=CurrentPage>1;btnNext.Enabled=CurrentPage<Pages;}catch(Exception){Error("Announcements are unavailable. Confirm the Communication migration and database connection.");}}protected void btnFilter_Click(object s,EventArgs e){CurrentPage=1;Bind();}protected void btnReset_Click(object s,EventArgs e){txtSearch.Text=txtFrom.Text=txtTo.Text="";ddlAudience.SelectedIndex=ddlPriority.SelectedIndex=ddlStatus.SelectedIndex=0;CurrentPage=1;Bind();}protected void btnPrev_Click(object s,EventArgs e){CurrentPage--;Bind();}protected void btnNext_Click(object s,EventArgs e){CurrentPage++;Bind();}protected void ddlPageSize_Changed(object s,EventArgs e){CurrentPage=1;Bind();}protected void btnNew_Click(object s,EventArgs e){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanManageAnnouncements);Open(null);}void Open(int? id){hidId.Value=id.HasValue?id.ToString():"";litFormTitle.Text=id.HasValue?"Edit Announcement":"New Announcement";txtTitle.Text=txtBody.Text=formPublish.Text=formExpiry.Text="";formPriority.SelectedValue="Normal";formAudience.SelectedValue="All Users";if(id.HasValue){DataRow r=Repo.Announcement(id.Value);if(r==null){Error("Announcement not found.");return;}txtTitle.Text=Convert.ToString(r["Title"]);txtBody.Text=Convert.ToString(r["Body"]);formPriority.SelectedValue=Convert.ToString(r["Priority"]);formAudience.SelectedValue=Convert.ToString(r["AudienceType"]);formPublish.Text=r["PublishDate"]==DBNull.Value?"":Convert.ToDateTime(r["PublishDate"]).ToString("yyyy-MM-ddTHH:mm");formExpiry.Text=r["ExpiryDate"]==DBNull.Value?"":Convert.ToDateTime(r["ExpiryDate"]).ToString("yyyy-MM-ddTHH:mm");Select(formRole,r["TargetRole"]);Select(formClass,r["TargetClassID"]);LoadSections();Select(formSection,r["TargetSectionID"]);}AudiencePanels();pnlForm.Visible=true;}void Select(ListControl c,object v){var x=c.Items.FindByValue(Convert.ToString(v));if(x!=null)c.SelectedValue=x.Value;}protected void formAudience_Changed(object s,EventArgs e){AudiencePanels();pnlForm.Visible=true;}void AudiencePanels(){pnlRole.Visible=formAudience.SelectedValue=="Specific Role";pnlClass.Visible=formAudience.SelectedValue=="Specific Class"||formAudience.SelectedValue=="Specific Section";pnlSection.Visible=formAudience.SelectedValue=="Specific Section";pnlUser.Visible=formAudience.SelectedValue=="Selected Users";}protected void formClass_Changed(object s,EventArgs e){LoadSections();AudiencePanels();pnlForm.Visible=true;}void Save(string status){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanManageAnnouncements);try{ValidateText(txtTitle.Text,txtBody.Text);DateTime? pub=DateValue(formPublish.Text),exp=DateValue(formExpiry.Text);if(status=="Scheduled"&&(!pub.HasValue||pub.Value<=DateTime.Now))throw new InvalidOperationException("Schedule date must be in the future.");if(exp.HasValue&&pub.HasValue&&exp<=pub)throw new InvalidOperationException("Expiry must be after publish date.");if(!CommunicationAuthorization.CanTargetSchoolWide(Role)&&formAudience.SelectedValue=="All Users")throw new UnauthorizedAccessException("Your role cannot publish school-wide announcements.");int? id=string.IsNullOrEmpty(hidId.Value)?(int?)null:V(hidId.Value);int aid=Repo.SaveAnnouncement(id,txtTitle.Text.Trim(),txtBody.Text.Trim(),formPriority.SelectedValue,formAudience.SelectedValue,V(formClass.SelectedValue)>0?(int?)V(formClass.SelectedValue):null,V(formSection.SelectedValue)>0?(int?)V(formSection.SelectedValue):null,formRole.SelectedValue,V(formUser.SelectedValue)>0?(int?)V(formUser.SelectedValue):null,pub,exp,status,UserId);if(upload.HasFile)SaveAttachment(aid);Repo.Log(UserId,"ANNOUNCEMENT_"+status.ToUpperInvariant(),"Announcement "+aid+" set to "+status,Ip);pnlForm.Visible=false;Success("Announcement saved as "+status+".");Bind();}catch(Exception ex){Error(ex.GetBaseException().Message);pnlForm.Visible=true;}}void SaveAttachment(int aid){string ext=Path.GetExtension(upload.FileName).ToLowerInvariant();string[] ok={".pdf",".docx",".xlsx",".jpg",".jpeg",".png"};if(Array.IndexOf(ok,ext)<0)throw new InvalidOperationException("Attachment type is not allowed.");if(upload.PostedFile.ContentLength>5*1024*1024)throw new InvalidOperationException("Attachment exceeds 5 MB.");string[] mime={"application/pdf","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","image/jpeg","image/png"};if(Array.IndexOf(mime,upload.PostedFile.ContentType.ToLowerInvariant())<0)throw new InvalidOperationException("Attachment content type is not allowed.");string stored=Guid.NewGuid().ToString("N")+ext,rel="~/Uploads/Communication/"+stored,dir=Server.MapPath("~/Uploads/Communication/");Directory.CreateDirectory(dir);string physical=Path.GetFullPath(Path.Combine(dir,stored)),root=Path.GetFullPath(dir);if(!physical.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Attachment path is invalid.");upload.SaveAs(physical);try{Repo.X("INSERT dbo.CommunicationAttachments(AnnouncementID,OriginalFileName,StoredFileName,RelativePath,ContentType,FileSize,UploadedByUserID)VALUES(@a,@o,@s,@r,@c,@z,@u)",new System.Data.SqlClient.SqlParameter("@a",aid),new System.Data.SqlClient.SqlParameter("@o",Path.GetFileName(upload.FileName)),new System.Data.SqlClient.SqlParameter("@s",stored),new System.Data.SqlClient.SqlParameter("@r",rel),new System.Data.SqlClient.SqlParameter("@c",upload.PostedFile.ContentType),new System.Data.SqlClient.SqlParameter("@z",upload.PostedFile.ContentLength),new System.Data.SqlClient.SqlParameter("@u",UserId));}catch{if(File.Exists(physical))File.Delete(physical);throw;}}protected void btnDraft_Click(object s,EventArgs e){Save("Draft");}protected void btnSchedule_Click(object s,EventArgs e){Save("Scheduled");}protected void btnPublish_Click(object s,EventArgs e){Save("Published");}protected void btnClose_Click(object s,EventArgs e){pnlForm.Visible=false;}protected void gv_RowCommand(object s,GridViewCommandEventArgs e){int id;if(!int.TryParse(Convert.ToString(e.CommandArgument),out id))return;if(e.CommandName=="ViewItem"){DataRow r=Repo.Announcement(id);if(r==null)return;litDetails.Text=D("Title",r["Title"])+D("Body",r["Body"])+D("Priority",r["Priority"])+D("Audience",r["AudienceType"])+D("Status",r["Status"])+D("Publish date",r["PublishDate"])+D("Expiry date",r["ExpiryDate"])+AttachmentLinks(id);pnlDetails.Visible=true;}else if(e.CommandName=="EditItem"){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanManageAnnouncements);Open(id);}else{CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanManageAnnouncements);if(e.CommandName=="DeleteItem"){if(!Repo.DeleteDraftAnnouncement(id))Error("Only draft announcements can be deleted.");else{Repo.Log(UserId,"ANNOUNCEMENT_DELETED","Draft announcement "+id+" deleted",Ip);Success("Draft announcement deleted.");}Bind();return;}string st=e.CommandName=="PublishItem"?"Published":e.CommandName=="UnpublishItem"?"Unpublished":"Cancelled";Repo.SetAnnouncementStatus(id,st,UserId);Repo.Log(UserId,"ANNOUNCEMENT_"+st.ToUpperInvariant(),"Announcement "+id+" set to "+st,Ip);Bind();}}string AttachmentLinks(int announcementId){DataTable t=Repo.AnnouncementAttachments(announcementId,UserId,Role);if(t.Rows.Count==0)return "";var b=new System.Text.StringBuilder("<dt>Attachments</dt><dd>");foreach(DataRow a in t.Rows)b.Append("<a class='btn btn-secondary' href='AttachmentDownload.aspx?id=").Append(a["AttachmentID"]).Append("'>Download ").Append(H(a["OriginalFileName"])).Append("</a> ");return b.Append("</dd>").ToString();}protected void btnDetailsClose_Click(object s,EventArgs e){pnlDetails.Visible=false;}string D(string k,object v){return "<dt>"+H(k)+"</dt><dd>"+H(v)+"</dd>";}void Success(string m){litMessage.Text="<div class='comm-note' role='status'>"+H(m)+"</div>";}void Error(string m){litMessage.Text="<div class='comm-error' role='alert'>"+H(m)+"</div>";}}}
